package com.example.application_service;
import com.example.application_service.entity.OutboxStatus;
import com.example.application_service.dto.ApplicationDtos;import com.example.application_service.exception.ApiException;import com.example.application_service.repository.*;import com.example.application_service.service.ApplicationService;import com.sun.net.httpserver.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.*;import org.springframework.test.web.servlet.MockMvc;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@Testcontainers @SpringBootTest(properties={"application-service.outbox.enabled=false","spring.rabbitmq.dynamic=false"}) @AutoConfigureMockMvc @TestMethodOrder(MethodOrderer.OrderAnnotation.class)
class ApplicationServiceApplicationTests{@Container static final PostgreSQLContainer<?> POSTGRES=new PostgreSQLContainer<>("postgres:17-alpine");static final UUID JOB=UUID.randomUUID(),CLOSED_JOB=UUID.randomUUID(),SLOW_JOB=UUID.randomUUID(),COMPANY=UUID.randomUUID(),CREATOR=UUID.randomUUID(),CANDIDATE=UUID.randomUUID(),CV=UUID.randomUUID(),EMPLOYER=UUID.randomUUID(),OUTSIDER=UUID.randomUUID();static final AtomicReference<String> JOB_TITLE=new AtomicReference<>("Platform Engineer");static final HttpServer STUB=stub();@Autowired MockMvc mvc;@Autowired ApplicationService service;@Autowired JobApplicationRepository applications;@Autowired ApplicationStatusHistoryRepository histories;@Autowired OutboxEventRepository outbox;@Autowired JdbcTemplate jdbc;
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.url",POSTGRES::getJdbcUrl);r.add("spring.datasource.username",POSTGRES::getUsername);r.add("spring.datasource.password",POSTGRES::getPassword);r.add("application-service.internal-token",()->"test-internal-secret");r.add("application-service.job-service-url",()->"http://localhost:"+STUB.getAddress().getPort());r.add("application-service.user-service-url",()->"http://localhost:"+STUB.getAddress().getPort());r.add("application-service.read-timeout",()->"150ms");r.add("application-service.circuit-breaker.failure-threshold",()->"3");}
 @AfterAll static void stop(){STUB.stop(0);}@BeforeEach void clean(){outbox.deleteAll();histories.deleteAll();applications.deleteAll();JOB_TITLE.set("Platform Engineer");}
 @Test @Order(1) void flywayAndHibernateValidateFreshPostgres(){Integer n=jdbc.queryForObject("select count(*) from information_schema.tables where table_schema='public' and table_name in ('applications','application_status_histories','outbox_events')",Integer.class);assertThat(n).isEqualTo(3);}
 @Test @Order(2) void candidateAppliesAndSnapshotsRemainImmutable()throws Exception{String id=apply(CANDIDATE,CV);JOB_TITLE.set("Changed upstream title");mvc.perform(get("/api/v1/applications/{id}",id).headers(identity(CANDIDATE,"CANDIDATE"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.application.jobTitle").value("Platform Engineer")).andExpect(jsonPath("$.data.application.candidateIdentity").value("candidate@example.com")).andExpect(jsonPath("$.data.history[0].toStatus").value("APPLIED"));assertThat(jdbc.queryForObject("select cv_object_key_snapshot from applications where id=?",String.class,UUID.fromString(id))).isEqualTo("private/cv.pdf");}
 @Test @Order(3) void roleOwnershipAndInvalidCvAreEnforced()throws Exception{mvc.perform(post("/api/v1/applications").headers(identity(EMPLOYER,"EMPLOYER")).contentType(MediaType.APPLICATION_JSON).content(applyJson(JOB,CV))).andExpect(status().isForbidden()).andExpect(jsonPath("$.code").value("ACCESS_DENIED"));mvc.perform(post("/api/v1/applications").headers(identity(CANDIDATE,"CANDIDATE")).contentType(MediaType.APPLICATION_JSON).content(applyJson(JOB,UUID.randomUUID()))).andExpect(status().isNotFound()).andExpect(jsonPath("$.code").value("CV_NOT_FOUND"));mvc.perform(post("/api/v1/applications").headers(identity(CANDIDATE,"CANDIDATE")).contentType(MediaType.APPLICATION_JSON).content(applyJson(CLOSED_JOB,CV))).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("JOB_APPLICATION_CLOSED"));}
 @Test @Order(4) void duplicateSequentialAndConcurrentApplyReturnConflict()throws Exception{apply(CANDIDATE,CV);mvc.perform(post("/api/v1/applications").headers(identity(CANDIDATE,"CANDIDATE")).contentType(MediaType.APPLICATION_JSON).content(applyJson(JOB,CV))).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("APPLICATION_ALREADY_EXISTS"));clean();ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch go=new CountDownLatch(1);var tasks=List.of(CompletableFuture.supplyAsync(()->concurrentApply(go),pool),CompletableFuture.supplyAsync(()->concurrentApply(go),pool));go.countDown();var results=tasks.stream().map(CompletableFuture::join).toList();pool.shutdownNow();assertThat(results).containsExactlyInAnyOrder("OK","APPLICATION_ALREADY_EXISTS");assertThat(applications.count()).isEqualTo(1);}
 @Test @Order(5) void candidateListAndDetailArePrivate()throws Exception{String id=apply(CANDIDATE,CV);mvc.perform(get("/api/v1/applications/me").headers(identity(CANDIDATE,"CANDIDATE"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.totalElements").value(1));mvc.perform(get("/api/v1/applications/{id}",id).headers(identity(UUID.randomUUID(),"CANDIDATE"))).andExpect(status().isForbidden()).andExpect(jsonPath("$.code").value("RESOURCE_FORBIDDEN"));mvc.perform(get("/api/v1/applications/me").headers(identity(CANDIDATE,"CANDIDATE")).param("sort","internalField")).andExpect(status().isBadRequest());}
 @Test @Order(6) void employerOwnershipListTransitionHistoryTerminalAndVersion()throws Exception{String id=apply(CANDIDATE,CV);mvc.perform(get("/api/v1/employer/jobs/{job}/applications",JOB).headers(identity(OUTSIDER,"EMPLOYER"))).andExpect(status().isForbidden());mvc.perform(get("/api/v1/employer/jobs/{job}/applications",JOB).headers(identity(EMPLOYER,"EMPLOYER"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.totalElements").value(1));long version=0;String[] flow={"SCREENING","INTERVIEW","OFFER","HIRED"};for(String next:flow){var result=mvc.perform(patch("/api/v1/applications/{id}/status",id).headers(identity(EMPLOYER,"EMPLOYER")).contentType(MediaType.APPLICATION_JSON).content("{\"newStatus\":\""+next+"\",\"note\":\"manual review\",\"version\":"+version+"}")).andExpect(status().isOk()).andReturn();version=tools.jackson.databind.json.JsonMapper.builder().build().readTree(result.getResponse().getContentAsString()).get("data").get("application").get("version").asLong();}mvc.perform(patch("/api/v1/applications/{id}/status",id).headers(identity(EMPLOYER,"EMPLOYER")).contentType(MediaType.APPLICATION_JSON).content("{\"newStatus\":\"REJECTED\",\"version\":"+version+"}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("INVALID_STATUS_TRANSITION"));mvc.perform(patch("/api/v1/applications/{id}/status",id).headers(identity(EMPLOYER,"EMPLOYER")).contentType(MediaType.APPLICATION_JSON).content("{\"newStatus\":\"REJECTED\",\"version\":0}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("OPTIMISTIC_LOCK_CONFLICT"));assertThat(histories.findByApplicationIdOrderByCreatedAtAsc(UUID.fromString(id))).hasSize(5);}
 @Test @Order(7) void dependencyTimeoutMapsTo503WithoutPartialWrite()throws Exception{mvc.perform(post("/api/v1/applications").headers(identity(CANDIDATE,"CANDIDATE")).contentType(MediaType.APPLICATION_JSON).content(applyJson(SLOW_JOB,CV))).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.code").value("DEPENDENCY_TIMEOUT"));assertThat(applications.count()).isZero();}
 @Test @Order(8) void correlationAndOpenApiWork()throws Exception{mvc.perform(get("/api/v1/applications/not-a-uuid").headers(identity(CANDIDATE,"CANDIDATE")).header("X-Correlation-ID","app-trace-1")).andExpect(status().isBadRequest()).andExpect(header().string("X-Correlation-ID","app-trace-1")).andExpect(jsonPath("$.traceId").value("app-trace-1"));mvc.perform(get("/v3/api-docs")).andExpect(status().isOk()).andExpect(jsonPath("$.paths['/api/v1/applications']").exists());}
 @Test @Order(9) void businessWritesAndOutboxAreAtomic()throws Exception{String id=apply(CANDIDATE,CV);assertThat(outbox.countByStatus(OutboxStatus.PENDING)).isEqualTo(1);mvc.perform(patch("/api/v1/applications/{id}/status",id).headers(identity(EMPLOYER,"EMPLOYER")).contentType(MediaType.APPLICATION_JSON).content("{\"newStatus\":\"SCREENING\",\"version\":0}")).andExpect(status().isOk());assertThat(outbox.countByStatus(OutboxStatus.PENDING)).isEqualTo(2);mvc.perform(patch("/api/v1/applications/{id}/status",id).headers(identity(EMPLOYER,"EMPLOYER")).contentType(MediaType.APPLICATION_JSON).content("{\"newStatus\":\"HIRED\",\"version\":1}")).andExpect(status().isConflict());assertThat(outbox.countByStatus(OutboxStatus.PENDING)).isEqualTo(2);}
 private String apply(UUID candidate,UUID cv)throws Exception{return tools.jackson.databind.json.JsonMapper.builder().build().readTree(mvc.perform(post("/api/v1/applications").headers(identity(candidate,"CANDIDATE")).contentType(MediaType.APPLICATION_JSON).content(applyJson(JOB,cv))).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString()).get("data").get("id").asText();}private String concurrentApply(CountDownLatch go){try{go.await();service.apply(new ApplicationDtos.Apply(JOB,CV,"Concurrent"),CANDIDATE,"candidate@example.com","concurrent");return "OK";}catch(ApiException e){return e.code();}catch(Exception e){return e.getClass().getSimpleName();}}private String applyJson(UUID job,UUID cv){return "{\"jobId\":\""+job+"\",\"cvId\":\""+cv+"\",\"coverLetter\":\"Interested\"}";}private org.springframework.http.HttpHeaders identity(UUID id,String role){var h=new org.springframework.http.HttpHeaders();h.set("X-User-Id",id.toString());h.set("X-User-Email",role.equals("CANDIDATE")?"candidate@example.com":"employer@example.com");h.set("X-User-Role",role);return h;}
 private static HttpServer stub(){try{HttpServer s=HttpServer.create(new InetSocketAddress(0),0);s.setExecutor(Executors.newCachedThreadPool());s.createContext("/internal/jobs/",e->{String p=e.getRequestURI().getPath();if(p.contains(SLOW_JOB.toString())){try{Thread.sleep(500);}catch(InterruptedException ignored){}}if(!p.contains(JOB.toString())&&!p.contains(CLOSED_JOB.toString())&&!p.contains(SLOW_JOB.toString())){respond(e,404,"{}");return;}boolean open=!p.contains(CLOSED_JOB.toString());String id=p.contains(CLOSED_JOB.toString())?CLOSED_JOB.toString():p.contains(SLOW_JOB.toString())?SLOW_JOB.toString():JOB.toString();respond(e,200,"{\"success\":true,\"data\":{\"jobId\":\""+id+"\",\"companyId\":\""+COMPANY+"\",\"createdBy\":\""+CREATOR+"\",\"title\":\""+JOB_TITLE.get()+"\",\"status\":\"PUBLISHED\",\"applicationDeadline\":\"2027-12-31\",\"acceptingApplications\":"+open+",\"version\":0}}");});s.createContext("/internal/cvs/",e->{if(!e.getRequestURI().getPath().contains(CV.toString())||!String.valueOf(e.getRequestURI().getQuery()).contains(CANDIDATE.toString())){respond(e,404,"{}");return;}respond(e,200,"{\"success\":true,\"data\":{\"cvId\":\""+CV+"\",\"candidateId\":\""+CANDIDATE+"\",\"fileName\":\"cv.pdf\",\"objectKey\":\"private/cv.pdf\",\"contentType\":\"application/pdf\",\"sizeBytes\":123,\"valid\":true}}");});s.createContext("/internal/companies/",e->{boolean ok=String.valueOf(e.getRequestURI().getQuery()).contains(EMPLOYER.toString());respond(e,200,"{\"success\":true,\"data\":{\"canManage\":"+ok+",\"memberRole\":"+(ok?"\"RECRUITER\"":"null")+"}}");});s.start();return s;}catch(IOException e){throw new ExceptionInInitializerError(e);}}private static void respond(HttpExchange e,int status,String body)throws IOException{byte[] b=body.getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","application/json");e.sendResponseHeaders(status,b.length);e.getResponseBody().write(b);e.close();}}
